FROM [synapse_fo].[PURCHLINE] T1
LEFT OUTER JOIN [synapse_fo].[DIMENSIONSETENTITY_RICS] T2 ON (
		(T1.DEFAULTDIMENSION = T2.RECID)
		AND (T1.PARTITION = T2.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONCOMBINATIONENTITY_RICS] T3 ON (
		(T1.LEDGERDIMENSION = T3.RECID)
		AND (T1.PARTITION = T3.PARTITION)
		)
--WHERE T1.PURCHID = 'RCS-000000'
